162	std::unique_ptr<ReadBufferFromFileBase> DiskWebServer::readFile(const String & path, const ReadSettings & read_settings, std::optional<size_t>, std::optional<size_t>) const
163	{
164	    LOG_TRACE(log, "Read from path: {}", path);
165	    auto iter = files.find(path);
166	    if (iter == files.end())
167	        throw Exception(ErrorCodes::FILE_DOESNT_EXIST, "File path {} does not exist", path);
168	
169	    auto fs_path = fs::path(url) / path;
170	    auto remote_path = fs_path.parent_path() / (escapeForFileName(fs_path.stem()) + fs_path.extension().string());
171	    remote_path = remote_path.string().substr(url.size());
172	
173	    StoredObjects objects;
174	    objects.emplace_back(remote_path, iter->second.size);
175	
176	    auto web_impl = std::make_unique<ReadBufferFromWebServerGather>(url, objects, getContext(), read_settings);
177	
178	    if (read_settings.remote_fs_method == RemoteFSReadMethod::threadpool)
179	    {
180	        auto reader = IObjectStorage::getThreadPoolReader();
181	        return std::make_unique<AsynchronousReadIndirectBufferFromRemoteFS>(reader, read_settings, std::move(web_impl), min_bytes_for_seek);
182	    }
183	    else
184	    {
185	        auto buf = std::make_unique<ReadIndirectBufferFromRemoteFS>(std::move(web_impl));
186	        return std::make_unique<SeekAvoidingReadBuffer>(std::move(buf), min_bytes_for_seek);
187	    }
188	}
