191	DirectoryIteratorPtr DiskWebServer::iterateDirectory(const String & path) const
192	{
193	    std::vector<fs::path> dir_file_paths;
194	    if (files.find(path) == files.end())
195	    {
196	        try
197	        {
198	            initialize(fs::path(url) / path);
199	        }
200	        catch (...)
201	        {
202	            const auto message = getCurrentExceptionMessage(false);
203	            bool can_throw = CurrentThread::isInitialized() && CurrentThread::get().getQueryContext();
204	            if (can_throw)
205	                throw Exception(ErrorCodes::NETWORK_ERROR, "Cannot load disk metadata. Error: {}", message);
206	
207	            LOG_TRACE(&Poco::Logger::get("DiskWeb"), "Cannot load disk metadata. Error: {}", message);
208	            return std::make_unique<DiskWebServerDirectoryIterator>(std::move(dir_file_paths));
209	        }
210	    }
211	
212	    if (files.find(path) == files.end())
213	        throw Exception("Directory '" + path + "' does not exist", ErrorCodes::DIRECTORY_DOESNT_EXIST);
214	
215	    for (const auto & file : files)
216	        if (parentPath(file.first) == path)
217	            dir_file_paths.emplace_back(file.first);
218	
219	    LOG_TRACE(log, "Iterate directory {} with {} files", path, dir_file_paths.size());
220	    return std::make_unique<DiskWebServerDirectoryIterator>(std::move(dir_file_paths));
221	}
