255	{
256	    auto creator = [](const String & disk_name,
257	                      const Poco::Util::AbstractConfiguration & config,
258	                      const String & config_prefix,
259	                      ContextPtr context,
260	                      const DisksMap & /*map*/) -> DiskPtr
261	    {
262	        String uri{config.getString(config_prefix + ".endpoint")};
263	        if (!uri.ends_with('/'))
264	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "URI must end with '/', but '{}' doesn't.", uri);
265	        try
266	        {
267	            Poco::URI poco_uri(uri);
268	        }
269	        catch (const Poco::Exception & e)
270	        {
271	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Bad URI: `{}`. Error: {}", uri, e.what());
272	        }
273	
274	        return std::make_shared<DiskWebServer>(disk_name, uri, context, config.getUInt64(config_prefix + ".min_bytes_for_seek", 1024 * 1024));
275	    };
276	
277	    factory.registerDiskType("web", creator);
